class Logo:
    @staticmethod
    def print(color: bool = True, size: int = 80, console: Console = Console()):
        """Print the logo to the console
        Args:
            color (bool): Whether to print the logo in color
            size (int): The size of the logo to print
            console (Console): The console to print the logo to
        """
        if color:
            if size == 80:
                console.print(logo_80_normal_colour)
            elif size == 120:
                console.print(logo_120_normal_colour)
            elif size == 160:
                console.print(logo_160_normal_colour)
            elif size == 200:
                console.print(logo_200_normal_colour)
        else:
            if size == 80:
                console.print(logo_80_normal)
            elif size == 120:
                console.print(logo_120_normal)
            elif size == 160:
                console.print(logo_160_normal)
            elif size == 200:
                console.print(logo_200_normal)

    @staticmethod
    def help():
        print("Sizes:")
        print("80, 120, 160, 200")

    @staticmethod
    def all():
        compiled = ""
        compiled += "\n\n\nlogo_80_normal\n\n"  + logo_80_normal
        compiled += "\n\n\nlogo_120_normal\n\n" + logo_120_normal
        compiled += "\n\n\nlogo_160_normal\n\n" + logo_160_normal
        compiled += "\n\n\nlogo_200_normal\n\n" + logo_200_normal

        compiled += "\n\n\nlogo_80_normal_colour\n\n"  + logo_80_normal_colour
        compiled += "\n\n\nlogo_120_normal_colour\n\n" + logo_120_normal_colour
        compiled += "\n\n\nlogo_160_normal_colour\n\n" + logo_160_normal_colour
        compiled += "\n\n\nlogo_200_normal_colour\n\n" + logo_200_normal_colour
        return compiled
